CREATE SCHEMA IF NOT EXISTS cart_api;
CREATE TABLE IF NOT EXISTS cart_api.users(id text PRIMARY KEY,username text UNIQUE NOT NULL,password_hash text NOT NULL,role text NOT NULL CHECK(role IN ('Customer','Admin')),member_tier text NOT NULL CHECK(member_tier IN ('normal','prime')));
CREATE TABLE IF NOT EXISTS cart_api.products(id text PRIMARY KEY,name text NOT NULL,description text NOT NULL DEFAULT '',category text NOT NULL DEFAULT '',image_url text NOT NULL DEFAULT '',price integer NOT NULL CHECK(price BETWEEN 1 AND 50000),weight_gram integer NOT NULL CHECK(weight_gram>0),stock integer NOT NULL CHECK(stock>=0),status text NOT NULL DEFAULT 'เปิดขาย' CHECK(status IN ('เปิดขาย','ปิดขาย')));
CREATE TABLE IF NOT EXISTS cart_api.coupons(code text PRIMARY KEY,percent integer NOT NULL CHECK(percent BETWEEN 0 AND 100),min_spend integer NOT NULL CHECK(min_spend>=0),status text NOT NULL DEFAULT 'เปิดใช้' CHECK(status IN ('เปิดใช้','ปิดใช้')));
CREATE TABLE IF NOT EXISTS cart_api.carts(user_id text PRIMARY KEY REFERENCES cart_api.users(id),stage text NOT NULL DEFAULT 'ตะกร้า' CHECK(stage IN ('ตะกร้า','ชำระเงิน','สำเร็จ')),coupon_code text REFERENCES cart_api.coupons(code),current_order_id text,notices jsonb NOT NULL DEFAULT '[]');
CREATE TABLE IF NOT EXISTS cart_api.cart_lines(user_id text REFERENCES cart_api.carts(user_id),product_id text REFERENCES cart_api.products(id),quantity integer NOT NULL CHECK(quantity BETWEEN 1 AND 10),PRIMARY KEY(user_id,product_id));
CREATE TABLE IF NOT EXISTS cart_api.orders(id text PRIMARY KEY,user_id text NOT NULL REFERENCES cart_api.users(id),status text NOT NULL DEFAULT 'รอชำระเงิน' CHECK(status IN ('รอชำระเงิน','ชำระเงินแล้ว','ยกเลิก')),snapshot jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE IF NOT EXISTS cart_api.order_lines(order_id text REFERENCES cart_api.orders(id),product_id text REFERENCES cart_api.products(id),name text NOT NULL,price integer NOT NULL CHECK(price>0),weight_gram integer NOT NULL CHECK(weight_gram>0),quantity integer NOT NULL CHECK(quantity BETWEEN 1 AND 10),PRIMARY KEY(order_id,product_id));
CREATE TABLE IF NOT EXISTS cart_api.sessions(token_hash text PRIMARY KEY,user_id text NOT NULL REFERENCES cart_api.users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS orders_owner_created ON cart_api.orders(user_id,created_at DESC);
CREATE OR REPLACE FUNCTION cart_api.protect_snapshot() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.snapshot IS DISTINCT FROM OLD.snapshot OR NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN RAISE EXCEPTION 'Order snapshots are immutable'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS immutable_order_snapshot ON cart_api.orders;
CREATE TRIGGER immutable_order_snapshot BEFORE UPDATE ON cart_api.orders FOR EACH ROW EXECUTE FUNCTION cart_api.protect_snapshot();
CREATE OR REPLACE FUNCTION cart_api.protect_order_line() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Order lines are immutable'; END $$;
DROP TRIGGER IF EXISTS immutable_order_line ON cart_api.order_lines;
CREATE TRIGGER immutable_order_line BEFORE UPDATE OR DELETE ON cart_api.order_lines FOR EACH ROW EXECUTE FUNCTION cart_api.protect_order_line();
DO $$ DECLARE t text; r text; BEGIN FOREACH t IN ARRAY ARRAY['users','products','coupons','carts','cart_lines','orders','order_lines','sessions'] LOOP EXECUTE format('ALTER TABLE cart_api.%I ENABLE ROW LEVEL SECURITY',t); END LOOP; REVOKE ALL ON SCHEMA cart_api FROM PUBLIC; REVOKE ALL ON ALL TABLES IN SCHEMA cart_api FROM PUBLIC; FOREACH r IN ARRAY ARRAY['anon','authenticated'] LOOP IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname=r) THEN EXECUTE format('REVOKE ALL ON SCHEMA cart_api FROM %I',r); EXECUTE format('REVOKE ALL ON ALL TABLES IN SCHEMA cart_api FROM %I',r); END IF; END LOOP; END $$;
